// GENERATED by `npm run contract:sync` in modules/ from modules/contract/index.ts. Do not edit this file: edit the source and run the script.
// The contract between the modules container and the Jellyflix apps: what the HTTP API says, as plain types.
// This file is the source of truth. `npm run contract:sync` (in modules/) copies it to web/src/core/modules/contract.ts, and the CI fails
// when the copy is out of date. It imports nothing, so it can be copied as it is.

/** Bumped when an answer changes in a way an older app would misread. The app says which versions it understands. */
export const API_VERSION = 1

export type ModuleId = 'channels' | 'match' | 'seerr'
export const MODULE_IDS: readonly ModuleId[] = ['channels', 'match', 'seerr']

export type ModuleState = 'ready' | 'needs-setup' | 'error'

/**
 * The revision of each module's own answers. Bumped when that module changes in a way an older app would misread, without touching the
 * others: an app that understands Retro TV revision 1 keeps using it while Match moves to 2. `API_VERSION` is for the container as a whole.
 */
export const MODULE_VERSIONS: Readonly<Record<ModuleId, number>> = { channels: 1, match: 2, seerr: 1 }

export interface ModuleInfo {
  id: ModuleId
  /** This module's revision (see `MODULE_VERSIONS`). A container older than this field leaves it out, and the app then assumes 1. */
  version: number
  state: ModuleState
  /** For a state that is not "ready": what is wrong, in English (the app translates what it knows). */
  detail?: string
}

/** What `GET /v1/manifest` answers: who the container is talking to, and which modules are on. */
export interface Manifest {
  api: number
  version: string
  /** The container's clock (seconds since the epoch), so the app can tell how far its own clock is off. */
  serverTime: number
  user: { id: string; name: string; isAdmin: boolean }
  modules: ModuleInfo[]
  /** True when the container has a Jellyfin API key (it can then read the library by night and look at other people's watched titles). */
  serviceKey: boolean
}

// ---------------------------------------------------------------------------------------------------------------------
// Channels ("Retro TV")
// ---------------------------------------------------------------------------------------------------------------------

/**
 * How the titles of a marathon follow each other. "interleave": series episode by episode, mixed with the rest.
 * "oldest": by year of release, the oldest first (a title without a year comes last).
 */
export type ChannelOrder = 'interleave' | 'sequential' | 'shuffle' | 'oldest'

/** Something Jellyfin has (a movie, an episode, a season, a series, a collection, a playlist, a library) that feeds a channel. */
export interface ItemSource {
  kind: 'item'
  id: string
  name: string
  /** What it is, as Jellyfin says ("Movie", "Series", "BoxSet"...), when known. */
  itemType?: string
}

/** Titles chosen by a rule instead of one by one. */
export interface RuleSource {
  kind: 'rule'
  name: string
  genres: string[]
  types: Array<'Movie' | 'Episode'>
  yearFrom?: number
  yearTo?: number
  /** Only titles the person who saves the channel has not watched. */
  unwatched?: boolean
  /** Only titles inside this library or folder. */
  libraryId?: string
  /** At most this many titles (random ones when there are more). */
  limit?: number
}

export type ChannelSource = ItemSource | RuleSource

/** A stretch of the week with its own sources. Days are 0 (Sunday) to 6; times are "HH:MM" in the channel's time zone. */
export interface TimeBlock {
  days: number[]
  start: string
  end: string
  /** Positions in the channel's `sources`; none means all of them. */
  sources: number[]
}

export interface ChannelDef {
  name: string
  /** What you "dial" to get here. */
  number: number
  /** A colour for the channel's tile. */
  color: string
  sources: ChannelSource[]
  /** "marathon": one list after another for ever. "grid": a week of time blocks. */
  mode: 'marathon' | 'grid'
  order: ChannelOrder
  blocks: TimeBlock[]
  /** IANA name, for the time blocks. */
  timezone: string
  /** A title is not repeated until this many others have been shown (grid mode). */
  avoidRepeat: number
  /** Marathon in "interleave" order: how many episodes of a series are shown before the channel moves on (1 to 5; 1 when missing). */
  episodesInARow?: number
  /** Titles longer than this many minutes are left out; 0 or missing means no limit. Ignored if it would leave nothing to show. */
  maxMinutes?: number
  enabled: boolean
}

export interface Channel extends ChannelDef {
  id: string
  /** How many titles the sources gave when they were last read. */
  poolSize: number
  /** When (seconds since the epoch), or null if never. */
  poolRefreshedAt: number | null
  createdAt: number
  imageVersion?: number
}

export interface Program {
  /** Seconds since the epoch. */
  start: number
  end: number
  itemId: string
  title: string
  /** An episode's series and number ("Naruto · S02E05"), or empty. */
  subtitle?: string
  type: 'Movie' | 'Episode'
  seriesId?: string
  /** Seconds. */
  runtime: number
  /**
   * True when this person's Jellyfin account may not see the title (a library or an age limit hidden from them): nothing of it is given,
   * `itemId` is empty and `title` is only a generic note. The times stay, so the shape of the schedule does.
   */
  unavailable?: boolean
}

/** What a program that cannot be shown to somebody is called (the apps translate it). */
export const UNAVAILABLE_PROGRAM = 'Program not available'

export interface ChannelSummary {
  id: string
  number: number
  name: string
  color: string
  enabled: boolean
  mode: 'marathon' | 'grid'
  /** How many titles the sources gave when they were last read, and when (seconds since the epoch; null if never). */
  poolSize: number
  poolRefreshedAt: number | null
  /** True when the person asking keeps this channel first (false when missing, as an older container says). */
  favorite?: boolean
  /** Changes whenever the picture of the channel does; missing when it has none. Asked for at `GET /v1/channels/:id/image`. */
  imageVersion?: number
  /** What is on right now, when the channel has a schedule. */
  now?: Program
  next?: Program
}

/** `GET /v1/channels/:id/window`: programs around a moment. */
export interface ChannelWindow {
  serverTime: number
  channel: { id: string; number: number; name: string; color: string; favorite?: boolean; imageVersion?: number }
  /** In order. */
  programs: Program[]
  /** The one that is on at `at`, or -1 when the channel is off the air. */
  currentIndex: number
}

export interface GuideChannel {
  id: string
  number: number
  name: string
  color: string
  /** True when the person asking keeps this channel first (false when missing, as an older container says). */
  favorite?: boolean
  /** Changes whenever the picture of the channel does; missing when it has none. Asked for at `GET /v1/channels/:id/image`. */
  imageVersion?: number
  programs: Program[]
}

export interface Guide {
  serverTime: number
  from: number
  to: number
  channels: GuideChannel[]
}

export interface ChannelPreview {
  poolSize: number
  programs: Program[]
  warnings: string[]
}

export interface ChannelSuggestions {
  genres: string[]
  collections: Array<{ id: string; name: string }>
}

/** `POST /v1/channels/auto`: one channel per genre or collection. */
export interface AutoChannelsRequest {
  genres: string[]
  collectionIds: string[]
  /** Kinds of title for the genre channels. */
  types: Array<'Movie' | 'Episode'>
}

// ---------------------------------------------------------------------------------------------------------------------
// Match ("swipe a film with someone")
// ---------------------------------------------------------------------------------------------------------------------

export interface MatchCard {
  id: string
  name: string
  /** A film, or a series (the first episode that has not been watched is what is played, from its page). */
  kind: 'Movie' | 'Series'
  year?: number
  overview?: string
  genres: string[]
  runtimeMinutes?: number
  rating?: number
  officialRating?: string
}

export type MatchVote = 'like' | 'pass'

/** How long a film is: under 90 minutes, from 90 to 120, or over 120. (A series counts as short or medium: its episodes are.) */
export type MatchLength = 'short' | 'medium' | 'long'

/** What the cards may be, chosen by whoever starts the Match. Nothing set means any film the person has not watched. */
export interface MatchFilters {
  genre?: string
  /** The first year of a decade: 1990 means 1990 to 1999. */
  decade?: number
  length?: MatchLength
  /** Series as well as films. */
  series?: boolean
}

/** How a finished Match went: how much the people agreed and what each chose. Only given once there is a winner. */
export interface MatchSummary {
  /** Rounds played (swiping and, if it came to that, choosing a favourite). */
  rounds: number
  /** The first round, where everybody saw the same cards: how many each liked and how many everybody liked. */
  firstRound?: {
    total: number
    both: number
    percent: number
    liked: Array<{ id: string; name: string; count: number }>
  }
  /** What each person chose as favourite, when it came to choosing. */
  picks: Array<{ id: string; name: string; card: string }>
}

/** What can be chosen when starting a Match, from the person's own Jellyfin. */
export interface MatchOptions {
  genres: string[]
}

/**
 * "lobby": people are joining (a Match for phones, before the host starts it). "swipe": everyone votes on the cards. "pick": the ones
 * everyone liked remain; everyone chooses a favourite. "done": there is a winner.
 */
export type MatchPhase = 'lobby' | 'swipe' | 'pick' | 'done'

/**
 * "local": one device, one person (or a group around it) decides: no code, nobody joins.
 * "phones": every person votes on their own phone with their own account; the device that started it shows the code and plays the winner.
 */
export type MatchMode = 'local' | 'phones'

export interface MatchMember {
  id: string
  name: string
  /** Has voted on every card of this round (or picked, in the pick phase). */
  done: boolean
}

export interface MatchRoomView {
  id: string
  /** What the other person types to join. */
  code: string
  mode: MatchMode
  /** Who started it, and so who starts the swiping and closes the Match. */
  hostId: string
  hostName: string
  /** Goes up with every change: the app asks again only when it moves. */
  version: number
  phase: MatchPhase
  round: number
  me: string
  members: MatchMember[]
  /** What the cards may be (as chosen when the Match started). */
  filters: MatchFilters
  /** Once there is a winner. */
  summary?: MatchSummary
  /** Every card of this round. */
  deck: MatchCard[]
  /** What I voted (by card id). The others' votes stay hidden until the round ends. */
  myVotes: Record<string, MatchVote>
  myPick?: string
  /** The cards I still have to vote on (swipe) or from which to choose (pick). */
  remaining: MatchCard[]
  /** At the end of a round: what everybody liked. */
  lastLiked: string[]
  winner?: MatchCard
  /** "agreement": everybody chose it. "coin": tied choices were settled by chance. "none": the people did not agree; there is no winner, only `finalists`. */
  winnerBy?: 'agreement' | 'coin' | 'none'
  /** When the Match ended without agreement: the films that came closest (most likes), best first, at most three. Empty if nobody liked any. */
  finalists?: MatchCard[]
}

export interface MatchRoomSummary {
  id: string
  code: string
  mode: MatchMode
  phase: MatchPhase
  members: string[]
  updatedAt: number
}

export interface MatchCreateRequest extends MatchFilters {
  /** How many cards in the first round (4 to 20, default 10). */
  deckSize?: number
  /** "local" (the default) or "phones": see {@link MatchMode}. */
  mode?: MatchMode
  /**
   * Couch mode (only for "local"): the names of the people on the sofa, 2 to 6, the first being whoever holds the remote and the account.
   * They vote one after the other on the same screen; the container keeps a seat for each. Nothing else changes: the same rounds, the same winner.
   */
  players?: string[]
}

// ---------------------------------------------------------------------------------------------------------------------
// Seerr ("ask for what the library does not have")
// ---------------------------------------------------------------------------------------------------------------------

export type SeerrMediaType = 'movie' | 'tv'

/**
 * Where a title stands. "available": in the library. "partial": some of it is (some seasons). "processing": approved and being fetched.
 * "pending": asked for, waiting for an administrator. "blocked": Seerr will not take requests for it. "none": nothing yet.
 */
export type SeerrStatus = 'available' | 'partial' | 'processing' | 'pending' | 'blocked' | 'none'

export interface SeerrTitle {
  mediaType: SeerrMediaType
  /** The TMDb id (what Seerr and a request use). */
  id: number
  title: string
  year?: number
  overview?: string
  /** A TMDb picture path such as "/abc.jpg"; the app builds the address (https://image.tmdb.org/t/p/w342 + path). */
  posterPath?: string
  status: SeerrStatus
  /** The title's id in Jellyfin, when Seerr knows it is in the library: "Open in Jellyflix". */
  jellyfinId?: string
}

export interface SeerrSearch {
  page: number
  totalPages: number
  results: SeerrTitle[]
}

export interface SeerrSeason {
  number: number
  name: string
  episodes?: number
  status: SeerrStatus
}

export interface SeerrDetail extends SeerrTitle {
  tagline?: string
  /** Series only; the specials (season 0) are left out. */
  seasons?: SeerrSeason[]
}

export interface SeerrQuota {
  /** Requests allowed in `days` days; absent when there is no limit. */
  limit?: number
  days?: number
  used: number
  remaining?: number
  /** True when the limit has been reached. */
  restricted: boolean
}

/** `GET /v1/seerr/me`: whether this person is in Seerr and what they may do there. */
export interface SeerrMe {
  canRequest: { movie: boolean; tv: boolean }
  quota: { movie?: SeerrQuota; tv?: SeerrQuota }
}

export interface SeerrRequestInput {
  mediaType: SeerrMediaType
  mediaId: number
  /** Series only: every season, or these (season numbers). */
  seasons?: 'all' | number[]
}

export type SeerrRequestStatus = 'pending' | 'approved' | 'declined' | 'failed' | 'completed'

export interface SeerrRequestView {
  id: number
  mediaType: SeerrMediaType
  mediaId: number
  title: string
  posterPath?: string
  /** What the request is (an administrator may approve or decline it). */
  status: SeerrRequestStatus
  /** Where the title itself stands. */
  mediaStatus: SeerrStatus
  seasons?: number[]
  /** ISO date. */
  createdAt: string
  jellyfinId?: string
}

export interface SeerrRequests {
  page: number
  totalPages: number
  results: SeerrRequestView[]
}

/** What `POST /v1/seerr/requests` answers. */
export interface SeerrRequestResult {
  requestId: number
  status: SeerrRequestStatus
}
